def inventory(orders: list[str], stock: dict[str, int]) -> list[str]:
    stock = dict(stock)
    filled = []

    def qty_of(text: str) -> int:
        if not text or not all("0" <= c <= "9" for c in text):
            return 0
        return int(text)

    for order in orders:
        parts = order.split(" ")
        bad = False
        needs: dict[str, int] = {}
        if len(parts) != 2 or not parts[0]:
            bad = True
            order_id = parts[0] if parts else ""
        else:
            order_id = parts[0]
            for entry in parts[1].split(","):
                pieces = entry.split(":")
                if len(pieces) != 2 or not pieces[0]:
                    bad = True
                    break
                item, qty_text = pieces
                qty = qty_of(qty_text)
                if qty <= 0 or item not in stock:
                    bad = True
                    break
                needs[item] = needs.get(item, 0) + qty
        if bad:
            raise ValueError("bad order " + order_id)

        if all(stock[item] >= q for item, q in needs.items()):
            for item, q in needs.items():
                stock[item] -= q
            filled.append(order_id)
    return filled
